async (page) => {
  const out = await page.evaluate(() => {
    const tbl = [...document.querySelectorAll('.ant-table table')]
      .find(t => [...t.querySelectorAll('th')].some(th => th.innerText.trim() === 'Failure reason'));
    const headers = [...tbl.querySelectorAll('th')].map(th => th.innerText.trim());
    const pi = headers.indexOf('Provider run');
    const row = tbl.querySelector('tr.ant-table-row');
    const cell = row.children[pi];
    const span = cell.querySelector('span[style*="max-width"]');
    const copy = cell.querySelector('.ant-typography-copy');
    const results = {};
    for (const w of [150, 140, 130, 120, 110, 100]) {
      span.style.maxWidth = w + 'px';
      void cell.offsetHeight;
      results[w] = {
        rowHeight: Math.round(row.getBoundingClientRect().height),
        wrapped: copy.getBoundingClientRect().top > span.getBoundingClientRect().bottom - 2,
        stillClipped: span.scrollWidth > Math.ceil(span.clientWidth),
      };
    }
    span.style.maxWidth = '150px';
    return results;
  });
  return JSON.stringify(out, null, 2);
}

