async (page) => {
  // Reads the session's own access token inside the page and uses it inline —
  // the token is never returned out of the browser.
  const out = await page.evaluate(async () => {
    let token = null;
    for (let i = 0; i < sessionStorage.length; i++) {
      const k = sessionStorage.key(i);
      if (k && k.startsWith('oidc.user:')) {
        try { token = JSON.parse(sessionStorage.getItem(k)).access_token; } catch {}
      }
    }
    if (!token) return { error: 'no token in sessionStorage' };
    const h = { Authorization: 'Bearer ' + token };
    const pr = await fetch('/api/v1/pipeline_runs?limit=5', { headers: h });
    const prj = pr.ok ? await pr.json() : null;
    const items = prj?.items ?? prj ?? [];
    const conns = await fetch('/api/v1/connections', { headers: h });
    const cj = conns.ok ? await conns.json() : null;
    const clist = cj?.items ?? cj ?? [];
    return {
      pipelineRuns: { status: pr.status, total: prj?.total ?? items.length,
        mostRecent: items[0] ? { provider: items[0].provider, pipeline: items[0].pipeline_or_dag_id,
          last_updated_at: items[0].last_updated_at, status: items[0].status } : null },
      orchestrationConnections: clist
        .filter(c => ['adf','airflow','dbt'].includes(c.type))
        .map(c => ({ name: c.name, type: c.type,
                     health: c.health_status ?? c.poll_health ?? null,
                     lastPollAt: c.last_poll_at ?? c.last_polled_at ?? null,
                     lastError: c.last_poll_error ?? null })),
    };
  });
  return JSON.stringify({ ...out, nowUtc: new Date().toISOString() }, null, 2);
}

async (page) => {
  const out = await page.evaluate(async () => {
    let token = null;
    for (let i = 0; i < sessionStorage.length; i++) {
      const k = sessionStorage.key(i);
      if (k && k.startsWith('oidc.user:')) { try { token = JSON.parse(sessionStorage.getItem(k)).access_token; } catch {} }
    }
    const h = { Authorization: 'Bearer ' + token, 'content-type': 'application/json' };
    const suites = await (await fetch('/api/v1/suites', { headers: h })).json();
    const list = suites.items ?? suites;
    const suite = list.find(s => /Orders \(all paths\)/.test(s.name)) ?? list[0];
    const start = await fetch(`/api/v1/suites/${suite.id}/run`, { method: 'POST', headers: h });
    if (!start.ok) return { error: `trigger ${start.status}`, suite: suite.name };
    const run = await start.json();
    // poll to completion
    let last = null;
    for (let i = 0; i < 40; i++) {
      await new Promise(r => setTimeout(r, 3000));
      const d = await (await fetch(`/api/v1/runs/${run.id}`, { headers: h })).json();
      last = d;
      if (['succeeded', 'failed', 'cancelled', 'error'].includes(d.status)) break;
    }
    return {
      suite: suite.name,
      runId: last.id,
      status: last.status,
      checks: last.results?.length ?? 0,
      outcomes: (last.results ?? []).reduce((a, r) => { a[r.status] = (a[r.status] || 0) + 1; return a; }, {}),
    };
  });
  return JSON.stringify(out, null, 2);
}

