    const pi = headers.indexOf('Provider run');
    const rows = [...tbl.querySelectorAll('tr.ant-table-row')];
    const measured = rows.map(r => {
      const s = r.children[pi]?.querySelector('span[style*="max-width"]');
      const c = r.children[pi]?.querySelector('.ant-typography-copy');
      if (!s || !c) return null;
      return {
        spanW: Math.round(s.getBoundingClientRect().width),
        clipped: s.scrollWidth > Math.ceil(s.clientWidth),
        wrapped: c.getBoundingClientRect().top > s.getBoundingClientRect().bottom - 2,
        rowHeight: Math.round(r.getBoundingClientRect().height),
      };
    }).filter(Boolean);
    return {
      rows: measured.length,
      anyWrapped: measured.some(m => m.wrapped),
      rowHeights: [...new Set(measured.map(m => m.rowHeight))],
      spanWidths: [...new Set(measured.map(m => m.spanW))],
      clippedCount: measured.filter(m => m.clipped).length,
    };
  });
  return JSON.stringify(out, null, 2);
}

